def load_panel(symbols=WATCH, source="stock", visible_through="2026-07-29"):
    """Return dict symbol -> DataFrame (date, close, volume...) restricted to visible window."""
    d = STOCK_DIR if source == "stock" else INDEX_DIR
    out = {}
